`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for decoder.
// Expected outputs come from isa_vectors.hex, generated by
// TP3/py/gen_vectors.py (run by sim/prebuild.bat) from the spec in
// docs/arquitectura.md 2.2/2.4, with the Python reference decoder (isa.py)
// deciding legality and register fields. About 3300 vectors: every
// instruction with random fields, rd = x0 cases, each opcode with random
// funct/other bits (mostly illegal), fully random words, and stop_code
// overrides.
//
// Vector layout (one line, 128 bits):
//   [31:0] imm (unused here)  [63:32] instr  [100:64] ctrl  [103:101] stop_code
// ctrl: [4:0] rs1 [9:5] rs2 [14:10] rd [18:15] alu_op [19] alu_src [20] link
//       [21] reg_write [22] mem_read [23] mem_write [26:24] funct3 [27] branch
//       [28] jalr [29] jal [32:30] imm_sel [33] halt_cond [36:34] halt_reason

module tb_decoder;

  localparam integer MAX_VEC  = 4096;
  localparam integer MIN_VEC  = 1000;  // fewer means the file did not load
  localparam integer N_VERBOSE = 5;    // print PASS for the first vectors

  reg [127:0] vec [0:MAX_VEC-1];

  reg  [31:0] instr = 32'h00000013;
  reg  [2:0]  stop_code = 3'd0;
  wire [4:0]  rs1, rs2, rd;
  wire [3:0]  alu_op;
  wire        alu_src, link, reg_write, mem_read, mem_write;
  wire [2:0]  funct3;
  wire        branch, jalr, jal;
  wire [2:0]  imm_sel;
  wire        halt_cond;
  wire [2:0]  halt_reason;

  decoder dut (
    .instr(instr), .stop_code(stop_code),
    .rs1(rs1), .rs2(rs2), .rd(rd), .alu_op(alu_op), .alu_src(alu_src),
    .link(link), .reg_write(reg_write), .mem_read(mem_read),
    .mem_write(mem_write), .funct3(funct3), .branch(branch), .jalr(jalr),
    .jal(jal), .imm_sel(imm_sel), .halt_cond(halt_cond),
    .halt_reason(halt_reason)
  );

  wire [36:0] got = {halt_reason, halt_cond, imm_sel, jal, jalr, branch,
                     funct3, mem_write, mem_read, reg_write, link, alu_src,
                     alu_op, rd, rs2, rs1};

  integer errors = 0;
  integer checks = 0;
  integer n, i;
  reg [36:0] expected;

  initial begin
    $readmemh("isa_vectors.hex", vec);
    n = 0;
    while (n < MAX_VEC && ^vec[n] !== 1'bx)
      n = n + 1;
    if (n < MIN_VEC) begin
      $display("FAIL: only %0d vectors loaded from isa_vectors.hex  TEST FAILED", n);
      errors = errors + 1;
    end

    for (i = 0; i < n; i = i + 1) begin
      instr     = vec[i][63:32];
      stop_code = vec[i][103:101];
      expected  = vec[i][100:64];
      #1;
      checks = checks + 1;
      if (got === expected) begin
        if (i < N_VERBOSE)
          $display("PASS vec %0d: instr=%08h stop=%0d -> ctrl=%010h", i, instr, stop_code, got);
      end else begin
        errors = errors + 1;
        $display("FAIL vec %0d: instr=%08h stop=%0d expected=%010h got=%010h diff=%010h  TEST FAILED",
                 i, instr, stop_code, expected, got, expected ^ got);
      end
    end

    if (errors == 0)
      $display("ALL TESTS PASSED (%0d checks)", checks);
    else
      $fatal(1, "%0d of %0d checks failed", errors, checks);
    $finish;
  end

endmodule

`default_nettype wire
